-- Generated by `make contracts` from contracts/census_county_pop.odcs.yaml. Do not edit: change the contract and regenerate.
-- Types the load the dataset's LATEST pointer names; every business rule lives in intermediate models.
-- No row is dropped or deduplicated: a duplicate key fails the model's one-row-per-key test.
select
  "SUMLEV" AS "sumlev",
  "REGION" AS "region",
  "DIVISION" AS "division",
  "STATE" AS "state_fips",
  "COUNTY" AS "county_fips",
  "STNAME" AS "state_name",
  "CTYNAME" AS "county_name",
  CASE WHEN CAST(NULLIF(trim("YEAR"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("YEAR"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("YEAR"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("YEAR"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('the publisher''s data has a value in year that has a fraction, so it isn''t a whole count') END AS "year",
  CASE WHEN CAST(NULLIF(trim("POPESTIMATE"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("POPESTIMATE"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("POPESTIMATE"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("POPESTIMATE"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('the publisher''s data has a value in population that has a fraction, so it isn''t a whole count') END AS "population",
  "_snapshot_id",
  "_raw_sha256"
from {{ source('raw', 'census_county_pop') }}
